# General Knowledge and General Awareness: history, culture, general polity
# and the Indian Constitution, plus India's neighbouring countries, which the
# SSC CPO 2026 notice (para 12.9.1.2) names. Static facts only: no current
# affairs and no current office-holders.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Constitution", "Which Article of the Constitution provides for the National Commission for Scheduled Castes?",
      ["Article 338", "Article 338A", "Article 340", "Article 324"],
      "Article 338 sets up the National Commission for Scheduled Castes. Article 338A is the commission for Scheduled Tribes and Article 340 the commission on backward classes."),
    S(1, 2, "Constitution", "Which Article of the Constitution says that no person accused of an offence shall be compelled to be a witness against himself?",
      ["Article 20", "Article 19", "Article 22", "Article 32"],
      "Article 20(3) protects against self-incrimination; Article 20 also bars ex post facto punishment and double jeopardy. Article 22 covers arrest and detention, and Article 32 the right to move the Supreme Court."),
    S(1, 2, "Modern history", "Which battle of 1764 confirmed British control over Bengal and Bihar and led to the grant of the Diwani?",
      ["Battle of Buxar", "Battle of Plassey", "Battle of Wandiwash", "Third Battle of Panipat"],
      "At Buxar (1764) the Company defeated the combined forces of Mir Qasim, the Nawab of Awadh and Shah Alam II; the Treaty of Allahabad (1765) gave it the Diwani. Plassey was in 1757."),
    S(1, 2, "Social reform", "Who founded the Bahishkrit Hitakarini Sabha in Bombay in 1924 to work for the uplift of the depressed classes?",
      ["B. R. Ambedkar", "Jyotirao Phule", "Sree Narayana Guru", "E. V. Ramasamy"],
      "B. R. Ambedkar founded the Bahishkrit Hitakarini Sabha in 1924 to spread education and improve the condition of the depressed classes. Phule founded the Satyashodhak Samaj in 1873 and E. V. Ramasamy led the Self-Respect Movement."),
    S(1, 1, "Culture", "Thang-Ta is a traditional martial art of which state?",
      ["Manipur", "Kerala", "Punjab", "Assam"],
      "Thang-Ta (sword and spear) comes from Manipur. Kalaripayattu is from Kerala and Gatka from Punjab."),
    S(1, 1, "Neighbouring countries", "Which neighbouring country shares a border with the Indian states of Sikkim, West Bengal, Assam and Arunachal Pradesh?",
      ["Bhutan", "Nepal", "Bangladesh", "Myanmar"],
      "Bhutan borders Sikkim, West Bengal, Assam and Arunachal Pradesh. Nepal does not touch Assam or Arunachal Pradesh, and Bangladesh does not touch Sikkim."),
    S(1, 2, "Art and architecture", "The Hoysala temples of Belur and Halebidu are in which present-day state?",
      ["Karnataka", "Tamil Nadu", "Andhra Pradesh", "Kerala"],
      "Belur and Halebidu, in Hassan district of Karnataka, hold the star-shaped Hoysala temples of the 12th century. They are a UNESCO World Heritage Site with Somanathapura."),
    S(1, 2, "Constitution", "Which Schedule of the Constitution deals with the administration of tribal areas in Assam, Meghalaya, Tripura and Mizoram?",
      ["Sixth Schedule", "Fifth Schedule", "Eleventh Schedule", "Seventh Schedule"],
      "The Sixth Schedule sets up autonomous district councils in those four states. The Fifth Schedule covers Scheduled Areas in other states and the Eleventh lists panchayat subjects."),
    S(1, 2, "Parliament", "Under which Article can Parliament create a new All India Service, once the Rajya Sabha has passed a resolution supporting it?",
      ["Article 312", "Article 315", "Article 309", "Article 311"],
      "Article 312 lets Parliament create All India Services after a Rajya Sabha resolution backed by two-thirds of members present and voting. Article 315 sets up public service commissions and Article 311 protects civil servants from arbitrary dismissal."),
    S(1, 2, "Ancient history", "Who discovered the Harappan site of Mohenjo-daro in 1922?",
      ["R. D. Banerji", "Daya Ram Sahni", "John Marshall", "Mortimer Wheeler"],
      "R. D. Banerji found Mohenjo-daro in 1922. Daya Ram Sahni excavated Harappa in 1921, and John Marshall directed the Archaeological Survey at the time."),
    S(1, 2, "National movement", "Who presided over the Lahore session of the Indian National Congress in 1929, where Purna Swaraj was adopted as the goal?",
      ["Jawaharlal Nehru", "Motilal Nehru", "Subhas Chandra Bose", "Vallabhbhai Patel"],
      "Jawaharlal Nehru presided at Lahore in December 1929, and the tricolour was hoisted on the banks of the Ravi. His father Motilal presided over the Calcutta session of 1928."),
    S(1, 2, "Neighbouring countries", "Which Indian state shares borders with Nepal, Bhutan and China?",
      ["Sikkim", "Arunachal Pradesh", "West Bengal", "Uttarakhand"],
      "Sikkim borders Nepal to the west, Bhutan to the east and the Tibet region of China to the north. West Bengal borders Nepal, Bhutan and Bangladesh; Arunachal Pradesh borders Bhutan, China and Myanmar."),
    S(1, 3, "Constitution", "Under which Article can the Supreme Court review its own judgment or order?",
      ["Article 137", "Article 143", "Article 131", "Article 136"],
      "Article 137 gives the Supreme Court power to review its own judgments. Article 136 is special leave to appeal, Article 131 its original jurisdiction and Article 143 the President's reference."),
    # ---------- Practice Test 2 ----------
    S(2, 3, "Parliament", "Under which Article can Parliament make laws on a State List subject if the Rajya Sabha passes a resolution saying it is in the national interest?",
      ["Article 249", "Article 250", "Article 252", "Article 253"],
      "Article 249 needs a Rajya Sabha resolution backed by two-thirds of members present and voting. Article 250 applies during an emergency, Article 252 when states consent and Article 253 to carry out international agreements."),
    S(2, 2, "Internal security", "Which Central Armed Police Force guards India's borders with Nepal and Bhutan?",
      ["Sashastra Seema Bal", "Border Security Force", "Assam Rifles", "Indo-Tibetan Border Police"],
      "The Sashastra Seema Bal is the border guarding force for Nepal (since 2001) and Bhutan (since 2004). The BSF guards the Pakistan and Bangladesh borders, the ITBP the China border and the Assam Rifles the Myanmar border."),
    S(2, 2, "Medieval history", "The Treaty of Purandar of 1665 was signed between Shivaji and which Mughal commander?",
      ["Raja Jai Singh", "Shaista Khan", "Afzal Khan", "Raja Jaswant Singh"],
      "Raja Jai Singh of Amber besieged Purandar and made Shivaji give up 23 forts under the treaty. Afzal Khan was a Bijapur general, and Shaista Khan was attacked by Shivaji at Pune in 1663."),
    S(2, 1, "Literature", "Who wrote the novel Anandamath, which contains the song Vande Mataram?",
      ["Bankim Chandra Chatterjee", "Rabindranath Tagore", "Sarat Chandra Chatterjee", "Ishwar Chandra Vidyasagar"],
      "Bankim Chandra Chatterjee published Anandamath in 1882. Tagore wrote Jana Gana Mana, the national anthem."),
    S(2, 1, "Culture", "Wangala, the 'hundred drums' harvest festival, is celebrated by the Garo people of which state?",
      ["Meghalaya", "Mizoram", "Nagaland", "Tripura"],
      "Wangala is the post-harvest festival of the Garos of Meghalaya, held to thank the sun god. Mizoram's Chapchar Kut and Nagaland's Hornbill Festival are different events."),
    S(2, 1, "Neighbouring countries", "The Kaladan Multi-Modal Transit Transport Project links Kolkata with Mizoram through which neighbouring country?",
      ["Myanmar", "Bangladesh", "Bhutan", "Nepal"],
      "The Kaladan project runs by sea from Kolkata to Sittwe port in Myanmar, up the Kaladan river and then by road into Mizoram, giving the north-east a route that avoids the Siliguri corridor."),
    S(2, 3, "Ancient history", "Who wrote the Sanskrit play Mudrarakshasa, about the rise of Chandragupta Maurya?",
      ["Vishakhadatta", "Ashvaghosha", "Banabhatta", "Kalidasa"],
      "Vishakhadatta's Mudrarakshasa tells how Chanakya won over the minister Rakshasa. Ashvaghosha wrote the Buddhacharita and Banabhatta the Harshacharita."),
    S(2, 1, "Constitution", "Which Part of the Constitution deals with the government of the states, including the Governor and the state legislatures?",
      ["Part VI", "Part V", "Part IV", "Part VIII"],
      "Part VI (Articles 152 to 237) covers the states: the Governor, the Council of Ministers, the state legislature and the High Courts. Part V covers the Union, Part IV the Directive Principles and Part VIII the Union Territories."),
    S(2, 2, "Parliament", "Under which Article can Parliament provide for settling disputes over the waters of inter-state rivers?",
      ["Article 262", "Article 263", "Article 280", "Article 249"],
      "Article 262 lets Parliament provide for the adjudication of inter-state river water disputes and bar the courts from them. Article 263 is about an Inter-State Council and Article 280 the Finance Commission."),
    S(2, 2, "Modern history", "The Ilbert Bill controversy of 1883 took place during the term of which Viceroy?",
      ["Lord Ripon", "Lord Lytton", "Lord Curzon", "Lord Dufferin"],
      "The Ilbert Bill, under Lord Ripon, proposed letting Indian judges try Europeans, and the European protest against it angered educated Indians."),
    S(2, 2, "National movement", "Who founded the Indian Association in Calcutta in 1876, along with Ananda Mohan Bose?",
      ["Surendranath Banerjee", "Dadabhai Naoroji", "Womesh Chandra Bonnerjee", "A. O. Hume"],
      "Surendranath Banerjee and Ananda Mohan Bose founded the Indian Association in 1876, one of the forerunners of the Congress. W. C. Bonnerjee presided over the first Congress session in 1885."),
    S(2, 3, "Constitution", "Under which Article is a State Election Commission set up to conduct panchayat elections?",
      ["Article 243K", "Article 243G", "Article 324", "Article 243E"],
      "Article 243K, added by the 73rd Amendment, gives panchayat elections to a State Election Commission. Article 324 covers the Election Commission of India, which does not run panchayat polls."),
    S(2, 2, "Art and architecture", "The Gommateshwara (Bahubali) statue at Shravanabelagola was commissioned by Chavundaraya, a minister of which dynasty?",
      ["Western Ganga", "Hoysala", "Rashtrakuta", "Pallava"],
      "Chavundaraya, minister of the Western Ganga kings, had the monolithic Bahubali statue carved in the late 10th century. The Hoysalas built Belur and Halebidu later, in the 12th century."),
    # ---------- Drill only ----------
    S(0, 2, "Constitution", "Article 350A asks every state to provide facilities for children of linguistic minorities to be taught in what at the primary stage?",
      ["Their mother tongue", "Hindi only", "English only", "Sanskrit"],
      "Article 350A says every state should try to provide instruction in the mother tongue at the primary stage to children of linguistic minority groups. Article 343 deals with the official language of the Union."),
    S(0, 2, "Modern history", "The Treaty of Salbai of 1782 ended which war?",
      ["First Anglo-Maratha War", "First Anglo-Mysore War", "First Anglo-Sikh War", "First Anglo-Burmese War"],
      "The Treaty of Salbai ended the First Anglo-Maratha War (1775 to 1782). The First Anglo-Mysore War ended with the Treaty of Madras in 1769."),
    S(0, 1, "Neighbouring countries", "Which of these Indian states shares a border with Myanmar?",
      ["Mizoram", "Tripura", "Meghalaya", "Sikkim"],
      "Myanmar borders Arunachal Pradesh, Nagaland, Manipur and Mizoram. Tripura and Meghalaya border only Bangladesh, and Sikkim borders Nepal, Bhutan and China."),
    S(0, 2, "Polity", "The Sarkaria Commission, set up in 1983, examined which subject?",
      ["Centre-state relations", "Police reforms", "Electoral reforms", "Tribal welfare"],
      "The Sarkaria Commission reported in 1988 on relations between the Union and the states, including the governor's role and Article 356. Police reforms were studied by other bodies."),
]
